    const itens=(ac.checklist||[]).filter(x=>x.irregularidade_codigo===codigo&&x.fonte_catalogo==='OFERTA'),origens=[...new Set(itens.map(x=>Number(x.catalogo_origem_id)).filter(Boolean))];
